/* ============================================
   INSTRUCTIONS COMPONENT
   Step-by-step guidance with numbered steps
   ============================================ */

.ds-instructions {
  display: flex;
  flex-direction: column;
  gap: var(--gap-400); /* 16px */
  width: 100%;
}

/* ============================================
   TITLE
   ============================================ */

.ds-instructions__title {
  font-family: var(--font-heading-3-family);
  font-size: var(--font-heading-3-size);
  font-weight: var(--font-heading-3-weight);
  line-height: var(--font-heading-3-line-height);
  letter-spacing: var(--font-heading-3-letter-spacing);
  color: var(--color-text-primary);
  margin: 0;
}

/* ============================================
   LIST
   ============================================ */

.ds-instructions__list {
  display: flex;
  flex-direction: column;
  gap: 0;
  list-style: none;
  margin: 0;
  padding: 0;
}

/* ============================================
   STEP
   ============================================ */

.ds-instructions__step {
  display: flex;
  gap: var(--gap-200); /* 8px */
}

/* ============================================
   INDICATOR (badge + connector)
   ============================================ */

.ds-instructions__indicator {
  display: flex;
  flex-direction: column;
  align-items: center;
  flex-shrink: 0;
}

.ds-instructions__badge {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  border-radius: var(--radius-pill);
  border: var(--border-025) solid var(--color-action-primary-border);
  background-color: transparent;
  flex-shrink: 0;
}

.ds-instructions__badge .material-symbols-rounded {
  --icon-size: var(--icon-size-600);
  color: var(--color-action-primary-bg);
}

.ds-instructions__number {
  font-family: var(--font-title-body-family);
  font-size: var(--font-paragraph-sm-size);
  font-weight: var(--font-title-body-weight);
  line-height: 1;
  color: var(--color-action-primary-bg);
}

.ds-instructions__dot {
  width: 8px;
  height: 8px;
  border-radius: var(--radius-pill);
  background-color: var(--color-action-primary-bg);
}

.ds-instructions__connector {
  width: var(--border-025); /* 1px */
  flex: 1;
  min-height: var(--padding-400); /* 16px */
  background-color: var(--color-bg-container-border);
}

/* ============================================
   CONTENT
   ============================================ */

.ds-instructions__content {
  display: flex;
  flex-direction: column;
  gap: var(--gap-050); /* 2px */
  padding-top: var(--padding-100); /* 4px — align text with badge center */
  padding-bottom: var(--padding-400); /* 16px — space before next step */
  min-width: 0;
}

.ds-instructions__step:last-child .ds-instructions__content {
  padding-bottom: 0;
}

.ds-instructions__label {
  font-family: var(--font-paragraph-emphasis-family);
  font-size: var(--font-paragraph-emphasis-size);
  font-weight: var(--font-paragraph-emphasis-weight);
  line-height: var(--font-paragraph-emphasis-line-height);
  letter-spacing: var(--font-paragraph-emphasis-letter-spacing);
  color: var(--color-text-primary);
  margin: 0;
}

.ds-instructions__description {
  font-family: var(--font-paragraph-family);
  font-size: var(--font-paragraph-size);
  font-weight: var(--font-paragraph-weight);
  line-height: var(--font-paragraph-line-height);
  letter-spacing: var(--font-paragraph-letter-spacing);
  color: var(--color-text-secondary);
  margin: 0;
}

/* ============================================
   HORIZONTAL LAYOUT
   ============================================ */

.ds-instructions--horizontal .ds-instructions__list {
  flex-direction: row;
}

.ds-instructions--horizontal .ds-instructions__step {
  flex-direction: column;
  align-items: center;
  text-align: center;
  flex: 1;
}

.ds-instructions--horizontal .ds-instructions__indicator {
  flex-direction: row;
  width: 100%;
}

.ds-instructions--horizontal .ds-instructions__connector {
  width: auto;
  height: var(--border-025); /* 1px */
  min-height: 0;
  min-width: 0;
  flex: 1;
  align-self: center;
}

.ds-instructions--horizontal .ds-instructions__content {
  padding-top: var(--padding-200); /* 8px */
  padding-bottom: 0;
}

/* ============================================
   SIZE — COMPACT
   ============================================ */

.ds-instructions--compact .ds-instructions__title {
  font-size: var(--font-title-body-size);
  line-height: var(--font-title-body-line-height);
}

.ds-instructions--compact .ds-instructions__badge {
  width: 24px;
  height: 24px;
}

.ds-instructions--compact .ds-instructions__badge .material-symbols-rounded {
  --icon-size: var(--icon-size-500);
}

.ds-instructions--compact .ds-instructions__number {
  font-size: 12px;
}

.ds-instructions--compact .ds-instructions__dot {
  width: 6px;
  height: 6px;
}

.ds-instructions--compact .ds-instructions__label {
  font-size: var(--font-paragraph-sm-size);
  line-height: var(--font-paragraph-sm-line-height);
  letter-spacing: var(--font-paragraph-sm-letter-spacing);
}

.ds-instructions--compact .ds-instructions__description {
  font-size: var(--font-paragraph-sm-size);
  line-height: var(--font-paragraph-sm-line-height);
  letter-spacing: var(--font-paragraph-sm-letter-spacing);
}

.ds-instructions--compact .ds-instructions__content {
  padding-top: var(--padding-050); /* 2px */
  padding-bottom: var(--padding-200); /* 8px */
}

.ds-instructions--compact .ds-instructions__step:last-child .ds-instructions__content {
  padding-bottom: 0;
}

import type React from 'react';
import './Instructions.css';
import '../../fonts/material-symbols.css';

export interface InstructionStep {
  /** Step label/title */
  label: string;
  /** Optional step description */
  description?: string;
  /** Optional custom icon — Material Symbol name (string) or custom element (ReactNode); defaults to step number */
  icon?: string | React.ReactNode;
}

export interface InstructionsProps {
  /** Instructions title */
  title?: string;
  /** Array of instruction steps */
  steps: InstructionStep[];
  /** Component size */
  size?: 'default' | 'compact';
  /** Layout direction */
  direction?: 'vertical' | 'horizontal';
  /** Whether to show step numbers instead of icons */
  numbered?: boolean;
  /** Additional CSS classes */
  className?: string;
}

/**
 * Instructions component for step-by-step guidance.
 * Displays an ordered list of steps with optional icons,
 * descriptions, and connecting lines.
 */
export const Instructions = ({
  title,
  steps,
  size = 'default',
  direction = 'vertical',
  numbered = true,
  className = '',
}: InstructionsProps) => {
  const baseClass = 'ds-instructions';
  const sizeClass = `${baseClass}--${size}`;
  const dirClass = `${baseClass}--${direction}`;

  const classes = [baseClass, sizeClass, dirClass, className]
    .filter(Boolean)
    .join(' ');

  return (
    <div className={classes}>
      {title && <h3 className={`${baseClass}__title`}>{title}</h3>}

      <ol className={`${baseClass}__list`}>
        {steps.map((step, idx) => (
          <li key={idx} className={`${baseClass}__step`}>
            <div className={`${baseClass}__indicator`}>
              <div className={`${baseClass}__badge`}>
                {step.icon ? (
                  typeof step.icon === 'string' ? (
                    <span className="material-symbols-rounded" aria-hidden="true">
                      {step.icon}
                    </span>
                  ) : (
                    <span aria-hidden="true">{step.icon}</span>
                  )
                ) : numbered ? (
                  <span className={`${baseClass}__number`}>{idx + 1}</span>
                ) : (
                  <span className={`${baseClass}__dot`} />
                )}
              </div>
              {idx < steps.length - 1 && (
                <div className={`${baseClass}__connector`} />
              )}
            </div>

            <div className={`${baseClass}__content`}>
              <p className={`${baseClass}__label`}>{step.label}</p>
              {step.description && (
                <p className={`${baseClass}__description`}>{step.description}</p>
              )}
            </div>
          </li>
        ))}
      </ol>
    </div>
  );
};
